1  import {Str} from 'expensify-common';
     2  import lodashMapValues from 'lodash/mapValues';
     3  import lodashSortBy from 'lodash/sortBy';
     4  import type {ForwardedRef} from 'react';
     5  import React, {forwardRef, useCallback, useEffect, useImperativeHandle, useMemo, useRef, useState} from 'react';
     6  import type {OnyxCollection} from 'react-native-onyx';
     7  import {useOnyx} from 'react-native-onyx';
     8  import * as Expensicons from '@components/Icon/Expensicons';
     9  import type {Mention} from '@components/MentionSuggestions';
    10  import MentionSuggestions from '@components/MentionSuggestions';
    11  import {usePersonalDetails} from '@components/OnyxProvider';
    12  import useArrowKeyFocusManager from '@hooks/useArrowKeyFocusManager';
    13  import useCurrentReportID from '@hooks/useCurrentReportID';
    14  import useCurrentUserPersonalDetails from '@hooks/useCurrentUserPersonalDetails';
    15  import useDebounce from '@hooks/useDebounce';
    16  import useLocalize from '@hooks/useLocalize';
    17  import localeCompare from '@libs/LocaleCompare';
    18  import * as LoginUtils from '@libs/LoginUtils';
    19  import * as PersonalDetailsUtils from '@libs/PersonalDetailsUtils';
    20  import getPolicyEmployeeAccountIDs from '@libs/PolicyEmployeeListUtils';
    21  import * as ReportUtils from '@libs/ReportUtils';
    22  import * as SuggestionsUtils from '@libs/SuggestionUtils';
    23  import {isValidRoomName} from '@libs/ValidationUtils';
    24  import * as ReportUserActions from '@userActions/Report';
    25  import CONST from '@src/CONST';
    26  import ONYXKEYS from '@src/ONYXKEYS';
    27  import type {PersonalDetails, PersonalDetailsList, Report} from '@src/types/onyx';
    28  import type {SuggestionsRef} from './ReportActionCompose';
    29  import type {SuggestionProps} from './Suggestions';
    30
    31  type SuggestionValues = {
    32      suggestedMentions: Mention[];
    33      atSignIndex: number;
    34      shouldShowSuggestionMenu: boolean;
    35      mentionPrefix: string;
    36      prefixType: string;
    37  };
    38
    39  /**
    40   * Check if this piece of string looks like a mention
    41   */
    42  const isMentionCode = (str: string): boolean => CONST.REGEX.HAS_AT_MOST_TWO_AT_SIGNS.test(str);
    43
    44  const defaultSuggestionsValues: SuggestionValues = {
    45      suggestedMentions: [],
    46      atSignIndex: -1,
    47      shouldShowSuggestionMenu: false,
    48      mentionPrefix: '',
    49      prefixType: '',
    50  };
    51
    52  type SuggestionPersonalDetailsList = Record<
    53      string,
    54      | (PersonalDetails & {
    55            weight: number;
    56        })
    57      | null
    58  >;
    59
    60  function getDisplayName(details: PersonalDetails) {
    61      const displayNameFromAccountID = ReportUtils.getDisplayNameForParticipant(details.accountID);
    62      if (!displayNameFromAccountID) {
    63          return details.login?.length ? details.login : '';
    64      }
    65      return displayNameFromAccountID;
    66  }
    67
    68  /**
    69   * Comparison function to sort users. It compares weights, display names, and accountIDs in that order
    70   */
    71  function compareUserInList(first: PersonalDetails & {weight: number}, second: PersonalDetails & {weight: number}) {
    72      if (first.weight !== second.weight) {
    73          return first.weight - second.weight;
    74      }
    75
    76      const displayNameLoginOrder = localeCompare(getDisplayName(first), getDisplayName(second));
    77      if (displayNameLoginOrder !== 0) {
    78          return displayNameLoginOrder;
    79      }
    80
    81      return first.accountID - second.accountID;
    82  }
    83
    84  function SuggestionMention(
    85      {value, selection, setSelection, updateComment, isAutoSuggestionPickerLarge, measureParentContainerAndReportCursor, isComposerFocused, isGroupPolicyReport, policyID}: SuggestionProps,
    86      ref: ForwardedRef<SuggestionsRef>,
    87  ) {
    88      const personalDetails = usePersonalDetails() ?? CONST.EMPTY_OBJECT;
    89      const {translate, formatPhoneNumber} = useLocalize();
    90      const [suggestionValues, setSuggestionValues] = useState(defaultSuggestionsValues);
    91      const suggestionValuesRef = useRef(suggestionValues);
    92      suggestionValuesRef.current = suggestionValues;
    93
    94      const [reports] = useOnyx(ONYXKEYS.COLLECTION.REPORT);
    95
    96      const currentUserPersonalDetails = useCurrentUserPersonalDetails();
    97      const isMentionSuggestionsMenuVisible = !!suggestionValues.suggestedMentions.length && suggestionValues.shouldShowSuggestionMenu;
    98
    99      const currentReportID = useCurrentReportID();
   100      const currentReport = reports?.[`${ONYXKEYS.COLLECTION.REPORT}${currentReportID?.currentReportID}`];
   101      // Smaller weight means higher order in suggestion list
   102      const getPersonalDetailsWeight = useCallback(
   103          (detail: PersonalDetails, policyEmployeeAccountIDs: number[]): number => {
   104              if (ReportUtils.isReportParticipant(detail.accountID, currentReport)) {
   105                  return 0;
   106              }
   107              if (policyEmployeeAccountIDs.includes(detail.accountID)) {
   108                  return 1;
   109              }
   110              return 2;
   111          },
   112          [currentReport],
   113      );
   114      const weightedPersonalDetails: PersonalDetailsList | SuggestionPersonalDetailsList = useMemo(() => {
   115          const policyEmployeeAccountIDs = getPolicyEmployeeAccountIDs(policyID);
   116          if (!ReportUtils.isGroupChat(currentReport) && !ReportUtils.doesReportBelongToWorkspace(currentReport, policyEmployeeAccountIDs, policyID)) {
   117              return personalDetails;
   118          }
   119          return lodashMapValues(personalDetails, (detail) =>
   120              detail
   121                  ? {
   122                        ...detail,
   123                        weight: getPersonalDetailsWeight(detail, policyEmployeeAccountIDs),
   124                    }
   125                  : null,
   126          );
   127      }, [policyID, currentReport, personalDetails, getPersonalDetailsWeight]);
   128
   129      const [highlightedMentionIndex, setHighlightedMentionIndex] = useArrowKeyFocusManager({
   130          isActive: isMentionSuggestionsMenuVisible,
   131          maxIndex: suggestionValues.suggestedMentions.length - 1,
   132          shouldExcludeTextAreaNodes: false,
   133      });
   134
   135      // Used to store the selection index of the last inserted mention
   136      const suggestionInsertionIndexRef = useRef<number | null>(null);
   137
   138      // Used to detect if the selection has changed since the last suggestion insertion
   139      // If so, we reset the suggestionInsertionIndexRef
   140      const hasSelectionChanged = !(selection.end === selection.start && selection.start === suggestionInsertionIndexRef.current);
   141      if (hasSelectionChanged) {
   142          suggestionInsertionIndexRef.current = null;
   143      }
   144
   145      // Used to decide whether to block the suggestions list from showing to prevent flickering
   146      const shouldBlockCalc = useRef(false);
   147
   148      /**
   149       * Search for reports suggestions in server.
   150       *
   151       * The function is debounced to not perform requests on every keystroke.
   152       */
   153      const debouncedSearchInServer = useDebounce(
   154          useCallback(() => {
   155              const foundSuggestionsCount = suggestionValues.suggestedMentions.length;
   156              if (suggestionValues.prefixType === '#' && foundSuggestionsCount < 5 && isGroupPolicyReport) {
   157                  ReportUserActions.searchInServer(value, policyID);
   158              }
   159          }, [suggestionValues.suggestedMentions.length, suggestionValues.prefixType, policyID, value, isGroupPolicyReport]),
   160          CONST.TIMING.SEARCH_OPTION_LIST_DEBOUNCE_TIME,
   161      );
   162
   163      const formatLoginPrivateDomain = useCallback(
   164          (displayText = '', userLogin = '') => {
   165              if (userLogin !== displayText) {
   166                  return displayText;
   167              }
   168              // If the emails are not in the same private domain, we also return the displayText
   169              if (!LoginUtils.areEmailsFromSamePrivateDomain(displayText, currentUserPersonalDetails.login ?? '')) {
   170                  return Str.removeSMSDomain(displayText);
   171              }
   172
   173              // Otherwise, the emails must be of the same private domain, so we should remove the domain part
   174              return displayText.split('@')[0];
   175          },
   176          [currentUserPersonalDetails.login],
   177      );
   178
   179      const getMentionCode = useCallback(
   180          (mention: Mention, mentionType: string): string => {
   181              if (mentionType === '#') {
   182                  // room mention case
   183                  return mention.handle ?? '';
   184              }
   185              return mention.text === CONST.AUTO_COMPLETE_SUGGESTER.HERE_TEXT ? CONST.AUTO_COMPLETE_SUGGESTER.HERE_TEXT : `@${formatLoginPrivateDomain(mention.handle, mention.handle)}`;
   186          },
   187          [formatLoginPrivateDomain],
   188      );
   189
   190      const insertSelectedMention = useCallback(
   191          (highlightedMentionIndexInner: number) => {
   192              // Extract the comment before and after the @ sign
   193              const commentBeforeAtSign = value.slice(0, suggestionValues.atSignIndex);
   194              const mentionObject = suggestionValues.suggestedMentions[highlightedMentionIndexInner];
   195              const mentionCode = `@${mentionObject.alternateText}`; // Use mention's alternateText like in the old code
   196
   197              // Remove the mention using regex like the old code
   198              const commentAfterAtSignWithMentionRemoved = value.slice(suggestionValues.atSignIndex).replace(CONST.REGEX.MENTION_REPLACER, '');
   199              // const trimmedCommentAfter = commentAfterAtSignWithMentionRemoved.trimStart(); // Trim leading space as per the old logic
   200
   201              // Update the comment with mention inserted
   202              updateComment(`${commentBeforeAtSign}${mentionCode} ${commentAfterAtSignWithMentionRemoved}`, true);
   203
   204              // Set selection position after the mention
   205              const selectionPosition = suggestionValues.atSignIndex + mentionCode.length + CONST.SPACE_LENGTH;
   206              setSelection({
   207                  start: selectionPosition,
   208                  end: selectionPosition,
   209              });
   210
   211              // Update suggestion-related values and reset
   212              suggestionInsertionIndexRef.current = selectionPosition;
   213              setSuggestionValues((prevState) => ({
   214                  ...prevState,
   215                  suggestedMentions: [],
   216                  shouldShowSuggestionMenu: false,
   217              }));
   218          },
   219          [
   220              value,
   221              suggestionValues.atSignIndex,
   222              suggestionValues.suggestedMentions,
   223              suggestionValues.prefixType,
   224              getMentionCode, // Updated to use the alternateText for mentions
   225              updateComment,
   226              setSelection,
   227          ],
   228      );
   229
   230
   231      /**
   232       * Clean data related to suggestions
   233       */
   234      const resetSuggestions = useCallback(() => {
   235          setSuggestionValues(defaultSuggestionsValues);
   236      }, []);
   237
   238      /**
   239       * Listens for keyboard shortcuts and applies the action
   240       */
   241      const triggerHotkeyActions = useCallback(
   242          (event: KeyboardEvent) => {
   243              const suggestionsExist = suggestionValues.suggestedMentions.length > 0;
   244
   245              if (((!event.shiftKey && event.key === CONST.KEYBOARD_SHORTCUTS.ENTER.shortcutKey) || event.key === CONST.KEYBOARD_SHORTCUTS.TAB.shortcutKey) && suggestionsExist) {
   246                  event.preventDefault();
   247                  if (suggestionValues.suggestedMentions.length > 0) {
   248                      insertSelectedMention(highlightedMentionIndex);
   249                      return true;
   250                  }
   251              }
   252
   253              if (event.key === CONST.KEYBOARD_SHORTCUTS.ESCAPE.shortcutKey) {
   254                  event.preventDefault();
   255
   256                  if (suggestionsExist) {
   257                      resetSuggestions();
   258                  }
   259
   260                  return true;
   261              }
   262          },
   263          [highlightedMentionIndex, insertSelectedMention, resetSuggestions, suggestionValues.suggestedMentions.length],
   264      );
   265
   266      const getUserMentionOptions = useCallback(
   267          (personalDetailsParam: PersonalDetailsList | SuggestionPersonalDetailsList, searchValue = ''): Mention[] => {
   268              const suggestions = [];
   269
   270              if (CONST.AUTO_COMPLETE_SUGGESTER.HERE_TEXT.includes(searchValue.toLowerCase())) {
   271                  suggestions.push({
   272                      text: CONST.AUTO_COMPLETE_SUGGESTER.HERE_TEXT,
   273                      alternateText: translate('mentionSuggestions.hereAlternateText'),
   274                      icons: [
   275                          {
   276                              source: Expensicons.Megaphone,
   277                              type: CONST.ICON_TYPE_AVATAR,
   278                          },
   279                      ],
   280                  });
   281              }
   282
   283              const filteredPersonalDetails = Object.values(personalDetailsParam ?? {}).filter((detail) => {
   284                  // If we don't have user's primary login, that member is not known to the current user and hence we do not allow them to be mentioned
   285                  if (!detail?.login || detail.isOptimisticPersonalDetail) {
   286                      return false;
   287                  }
   288                  // We don't want to mention system emails like notifications@expensify.com
   289                  if (CONST.RESTRICTED_EMAILS.includes(detail.login) || CONST.RESTRICTED_ACCOUNT_IDS.includes(detail.accountID)) {
   290                      return false;
   291                  }
   292                  const displayName = PersonalDetailsUtils.getDisplayNameOrDefault(detail);
   293                  const displayText = displayName === formatPhoneNumber(detail.login) ? displayName : `${displayName} ${detail.login}`;
   294                  if (searchValue && !displayText.toLowerCase().includes(searchValue.toLowerCase())) {
   295                      return false;
   296                  }
   297
   298                  // Given the mention is inserted by user, we don't want to show the mention options unless the
   299                  // selection index changes. In that case, suggestionInsertionIndexRef.current will be null.
   300                  // See https://github.com/Expensify/App/issues/38358 for more context
   301                  if (suggestionInsertionIndexRef.current) {
   302                      return false;
   303                  }
   304
   305                  return true;
   306              }) as Array<PersonalDetails & {weight: number}>;
   307
   308              // At this point we are sure that the details are not null, since empty user details have been filtered in the previous step
   309              const sortedPersonalDetails = filteredPersonalDetails.sort(compareUserInList);
   310
   311              sortedPersonalDetails.slice(0, CONST.AUTO_COMPLETE_SUGGESTER.MAX_AMOUNT_OF_SUGGESTIONS - suggestions.length).forEach((detail) => {
   312                  suggestions.push({
   313                      text: formatLoginPrivateDomain(PersonalDetailsUtils.getDisplayNameOrDefault(detail), detail?.login),
   314                      alternateText: `@${formatLoginPrivateDomain(detail?.login, detail?.login)}`,
   315                      handle: detail?.login,
   316                      icons: [
   317                          {
   318                              name: detail?.login,
   319                              source: detail?.avatar ?? Expensicons.FallbackAvatar,
   320                              type: CONST.ICON_TYPE_AVATAR,
   321                              fallbackIcon: detail?.fallbackIcon,
   322                              id: detail?.accountID,
   323                          },
   324                      ],
   325                  });
   326              });
   327
   328              return suggestions;
   329          },
   330          [translate, formatPhoneNumber, formatLoginPrivateDomain],
   331      );
   332
   333      const getRoomMentionOptions = useCallback(
   334          (searchTerm: string, reportBatch: OnyxCollection<Report>): Mention[] => {
   335              const filteredRoomMentions: Mention[] = [];
   336              Object.values(reportBatch ?? {}).forEach((report) => {
   337                  if (!ReportUtils.canReportBeMentionedWithinPolicy(report, policyID ?? '-1')) {
   338                      return;
   339                  }
   340                  if (report?.reportName?.toLowerCase().includes(searchTerm.toLowerCase())) {
   341                      filteredRoomMentions.push({
   342                          text: report.reportName,
   343                          handle: report.reportName,
   344                          alternateText: report.reportName,
   345                      });
   346                  }
   347              });
   348
   349              return lodashSortBy(filteredRoomMentions, 'handle').slice(0, CONST.AUTO_COMPLETE_SUGGESTER.MAX_AMOUNT_OF_SUGGESTIONS);
   350          },
   351          [policyID],
   352      );
   353
   354      const calculateMentionSuggestion = useCallback(
   355          (newValue: string, selectionStart?: number, selectionEnd?: number) => {
   356              if (selectionEnd !== selectionStart || !selectionEnd || shouldBlockCalc.current || selectionEnd < 1 || !isComposerFocused) {
   357                  shouldBlockCalc.current = false;
   358                  resetSuggestions();
   359                  return;
   360              }
   361
   362              const afterLastBreakLineIndex = newValue.lastIndexOf('\n', selectionEnd - 1) + 1;
   363              const leftString = newValue.substring(afterLastBreakLineIndex, selectionEnd);
   364              const words = leftString.split(CONST.REGEX.SPACE_OR_EMOJI);
   365              const lastWord: string = words.at(-1) ?? '';
   366              const secondToLastWord = words[words.length - 3];
   367
   368              let atSignIndex: number | undefined;
   369              let suggestionWord = '';
   370              let prefix: string;
   371              let prefixType = '';
   372
   373              // Detect if the last two words contain a mention (two words are needed to detect a mention with a space in it)
   374              if (lastWord.startsWith('@') || lastWord.startsWith('#')) {
   375                  atSignIndex = leftString.lastIndexOf(lastWord) + afterLastBreakLineIndex;
   376                  suggestionWord = lastWord;
   377
   378                  prefix = suggestionWord.substring(1);
   379                  prefixType = suggestionWord.substring(0, 1);
   380              } else if (secondToLastWord && secondToLastWord.startsWith('@') && secondToLastWord.length > 1) {
   381                  atSignIndex = leftString.lastIndexOf(secondToLastWord) + afterLastBreakLineIndex;
   382                  suggestionWord = `${secondToLastWord} ${lastWord}`;
   383
   384                  prefix = suggestionWord.substring(1);
   385                  prefixType = suggestionWord.substring(0, 1);
   386              } else {
   387                  prefix = lastWord.substring(1);
   388              }
   389
   390              const nextState: Partial<SuggestionValues> = {
   391                  suggestedMentions: [],
   392                  atSignIndex,
   393                  mentionPrefix: prefix,
   394                  prefixType,
   395              };
   396
   397              if (isMentionCode(suggestionWord) && prefixType === '@') {
   398                  const suggestions = getUserMentionOptions(weightedPersonalDetails, prefix);
   399                  nextState.suggestedMentions = suggestions;
   400                  nextState.shouldShowSuggestionMenu = !!suggestions.length;
   401              }
   402
   403              const shouldDisplayRoomMentionsSuggestions = isGroupPolicyReport && (isValidRoomName(suggestionWord.toLowerCase()) || prefix === '');
   404              if (prefixType === '#' && shouldDisplayRoomMentionsSuggestions) {
   405                  // Filter reports by room name and current policy
   406                  nextState.suggestedMentions = getRoomMentionOptions(prefix, reports);
   407
   408                  // Even if there are no reports, we should show the suggestion menu - to perform live search
   409                  nextState.shouldShowSuggestionMenu = true;
   410              }
   411
   412              // Early return if there is no update
   413              const currentState = suggestionValuesRef.current;
   414              if (currentState.suggestedMentions.length === 0 && nextState.suggestedMentions?.length === 0) {
   415                  return;
   416              }
   417
   418              setSuggestionValues((prevState) => ({
   419                  ...prevState,
   420                  ...nextState,
   421              }));
   422              setHighlightedMentionIndex(0);
   423          },
   424          [isComposerFocused, isGroupPolicyReport, setHighlightedMentionIndex, resetSuggestions, getUserMentionOptions, weightedPersonalDetails, getRoomMentionOptions, reports],
   425      );
   426
   427      useEffect(() => {
   428          calculateMentionSuggestion(value, selection.start, selection.end);
   429      }, [value, selection, calculateMentionSuggestion]);
   430
   431      useEffect(() => {
   432          debouncedSearchInServer();
   433      }, [suggestionValues.suggestedMentions.length, suggestionValues.prefixType, policyID, value, debouncedSearchInServer]);
   434
   435      const updateShouldShowSuggestionMenuToFalse = useCallback(() => {
   436          setSuggestionValues((prevState) => {
   437              if (prevState.shouldShowSuggestionMenu) {
   438                  return {...prevState, shouldShowSuggestionMenu: false};
   439              }
   440              return prevState;
   441          });
   442      }, []);
   443
   444      const setShouldBlockSuggestionCalc = useCallback(
   445          (shouldBlockSuggestionCalc: boolean) => {
   446              shouldBlockCalc.current = shouldBlockSuggestionCalc;
   447          },
   448          [shouldBlockCalc],
   449      );
   450
   451      const getSuggestions = useCallback(() => suggestionValues.suggestedMentions, [suggestionValues]);
   452      const getIsSuggestionsMenuVisible = useCallback(() => isMentionSuggestionsMenuVisible, [isMentionSuggestionsMenuVisible]);
   453
   454      useImperativeHandle(
   455          ref,
   456          () => ({
   457              resetSuggestions,
   458              triggerHotkeyActions,
   459              setShouldBlockSuggestionCalc,
   460              updateShouldShowSuggestionMenuToFalse,
   461              getSuggestions,
   462              getIsSuggestionsMenuVisible,
   463          }),
   464          [resetSuggestions, setShouldBlockSuggestionCalc, triggerHotkeyActions, updateShouldShowSuggestionMenuToFalse, getSuggestions, getIsSuggestionsMenuVisible],
   465      );
   466
   467      if (!isMentionSuggestionsMenuVisible) {
   468          return null;
   469      }
   470
   471      return (
   472          <MentionSuggestions
   473              highlightedMentionIndex={highlightedMentionIndex}
   474              mentions={suggestionValues.suggestedMentions}
   475              prefix={suggestionValues.mentionPrefix}
   476              onSelect={insertSelectedMention}
   477              isMentionPickerLarge={!!isAutoSuggestionPickerLarge}
   478              measureParentContainerAndReportCursor={measureParentContainerAndReportCursor}
   479              resetSuggestions={resetSuggestions}
   480          />
   481      );
   482  }
   483
   484  SuggestionMention.displayName = 'SuggestionMention';
   485
   486  export default forwardRef(SuggestionMention);
   487
   488  export {compareUserInList};

