    96                                  name={item.icons[0].name}
    97                                  avatarID={item.icons[0].id}
    98                                  type={item.icons[0].type}
    99                                  fill={isIcon ? theme.success : undefined}
   100                                  fallbackIcon={item.icons[0].fallbackIcon}
   101                              />
   102                          </View>
   103                      )}
   104                      <Text
   105                          style={[styles.mentionSuggestionsText, styles.flexShrink1]}
   106                          numberOfLines={1}
   107                      >
   108                          {styledDisplayName?.map(({text, isColored}, i) => (
   109                              <Text
   110                                  // eslint-disable-next-line react/no-array-index-key
   111                                  key={`${text}${i}`}
   112                                  style={[StyleUtils.getColoredBackgroundStyle(isColored), styles.mentionSuggestionsDisplayName]}
   113                              >
   114                                  {text}
   115                              </Text>
   116                          ))}
   117                      </Text>
   118                      <Text
   119                          style={[styles.mentionSuggestionsText, styles.flex1]}
   120                          numberOfLines={1}
   121                      >
   122                          {styledHandle?.map(
