   124                                  !!text && (
   125                                      <Text
   126                                          // eslint-disable-next-line react/no-array-index-key
   127                                          key={`${text}${i}`}
   128                                          style={[StyleUtils.getColoredBackgroundStyle(isColored), styles.textSupporting]}
   129                                      >
   130                                          {text}
   131                                      </Text>
   132                                  ),
   133                          )}
   134                      </Text>
   135                  </View>
   136              );
   137          },
   138          [
   139              prefix,
   140              styles.autoCompleteSuggestionContainer,
   141              styles.ph2,
   142              styles.mentionSuggestionsAvatarContainer,
   143              styles.mentionSuggestionsText,
   144              styles.flexShrink1,
   145              styles.flex1,
   146              styles.mentionSuggestionsDisplayName,
   147              styles.textSupporting,
   148              theme.success,
   149              StyleUtils,
   150          ],
   151      );
   152
   153      return (
   154          <AutoCompleteSuggestions
   155              suggestions={mentions}
   156              renderSuggestionMenuItem={renderSuggestionMenuItem}
   157              keyExtractor={keyExtractor}
   158              highlightedSuggestionIndex={highlightedMentionIndex}
   159              onSelect={onSelect}
   160              isSuggestionPickerLarge={isMentionPickerLarge}
   161              accessibilityLabelExtractor={keyExtractor}
   162              measureParentContainerAndReportCursor={measureParentContainerAndReportCursor}
   163              resetSuggestions={resetSuggestions}
   164          />
   165      );
   166  }
   167
   168  MentionSuggestions.displayName = 'MentionSuggestions';
   169
   170  export default MentionSuggestions;
   171
   172  export type {Mention};

